function freeTimeSlotsFaithful(inputValueArray) {
  const items = [{ json: { value: inputValueArray } }];
  // ===== 模板 2786 freeTimeSlots 节点原文开始 =====
  const businessHoursStart = "08:00:00Z";  // Business hours start time
  const businessHoursEnd = "17:30:00Z";    // Business hours end time

  const inputData = items[0].json.value;

  function getDateWithTime(dateString, time) {
    const datePart = new Date(dateString).toISOString().split("T")[0];
    return new Date(`${datePart}T${time}`);
  }
  function getDayOfWeek(dateString) {
    const daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
    return daysOfWeek[new Date(dateString).getUTCDay()];
  }
  function addDays(date, days) {
    const result = new Date(date);
    result.setDate(result.getDate() + days);
    return result;
  }
  function formatDate(date) {
    return date.toISOString().split('T')[0];
  }
  const defaultTimeZone = inputData.length > 0 && inputData[0].start && inputData[0].start.timeZone
    ? inputData[0].start.timeZone
    : "UTC";

  let minDate = null;
  let maxDate = null;
  inputData.forEach(event => {
    if (event.start && event.start.dateTime) {
      const eventDate = new Date(event.start.dateTime);
      if (!minDate || eventDate < minDate) { minDate = eventDate; }
      if (!maxDate || eventDate > maxDate) { maxDate = eventDate; }
    }
  });
  if (minDate && maxDate) {
    minDate = new Date(minDate.toISOString().split('T')[0]);
    maxDate = new Date(maxDate.toISOString().split('T')[0]);
  }

  const eventsByDate = {};
  inputData.forEach(event => {
    if (event.start && event.start.dateTime) {
      const eventDate = new Date(event.start.dateTime).toISOString().split("T")[0];
      if (!eventsByDate[eventDate]) { eventsByDate[eventDate] = []; }
      if (event.showAs === "busy") {
        eventsByDate[eventDate].push({
          start: new Date(event.start.dateTime),
          end: new Date(event.end.dateTime),
          timeZone: event.start.timeZone || defaultTimeZone
        });
      }
    }
  });

  const freeTimeSlots = [];
  if (minDate && maxDate) {
    for (let currentDate = new Date(minDate); currentDate <= maxDate; currentDate = addDays(currentDate, 1)) {
      const dateStr = formatDate(currentDate);
      const busyEvents = eventsByDate[dateStr] || [];
      const businessStart = getDateWithTime(dateStr, businessHoursStart);
      const businessEnd = getDateWithTime(dateStr, businessHoursEnd);
      if (busyEvents.length === 0) {
        freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: businessStart.toISOString(), freeEnd: businessEnd.toISOString(), timeZone: defaultTimeZone });
        continue;
      }
      busyEvents.sort((a, b) => a.start - b.start);
      if (busyEvents[0].start > businessStart) {
        freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: businessStart.toISOString(), freeEnd: busyEvents[0].start.toISOString(), timeZone: busyEvents[0].timeZone });
      }
      for (let i = 0; i < busyEvents.length - 1; i++) {
        if (busyEvents[i].end < busyEvents[i+1].start) {
          freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: busyEvents[i].end.toISOString(), freeEnd: busyEvents[i+1].start.toISOString(), timeZone: busyEvents[i].timeZone });
        }
      }
      if (busyEvents[busyEvents.length - 1].end < businessEnd) {
        freeTimeSlots.push({ date: dateStr, dayOfWeek: getDayOfWeek(dateStr), freeStart: busyEvents[busyEvents.length - 1].end.toISOString(), freeEnd: businessEnd.toISOString(), timeZone: busyEvents[busyEvents.length - 1].timeZone });
      }
    }
  }
  return [{ json: { freeTimeSlots } }];
  // ===== 模板 2786 freeTimeSlots 节点原文结束 =====
}


// ============ 忠实复刻：If / Switch / varResponse 节点语义 ============
// If 节点 tv2.2：chatInput exists (string, operation=exists)
const chatInputExists = o => o.chatInput !== undefined && o.chatInput !== null;
// Switch 节点 tv3.2：route 严格等于 availability / message（strict typeValidation）
const switchRoute = route => (route === 'availability') ? 'out0:availability'
                          : (route === 'message') ? 'out1:message' : 'drop(无default分支,静默丢)';
// varResponse Set：response = freeTimeSlots.toJsonString() → 数组被序列化成 JSON 字符串
const toJsonStringPolyfill = arr => JSON.stringify(arr);

// ============ 断言驱动 ============
const results = [];
function T(name, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  results.push({ name, ok, actual, expected: ok ? undefined : expected });
}
const ev = (s, e, showAs) => ({ start: { dateTime: s, timeZone: 'Europe/London' }, end: { dateTime: e, timeZone: 'Europe/London' }, showAs: showAs || 'busy' });

// --- freeTimeSlots（11 断言）---
// FS1 单日无事件 → 全天营业时段 08:00-17:30
let fs1 = freeTimeSlotsFaithful([])[0].json.freeTimeSlots;
T('FS1 空日历 → 0 槽（无 min/max 日期，循环不跑）', fs1.length, 0);

let fs2 = freeTimeSlotsFaithful([ev('2026-10-05T10:00:00Z','2026-10-05T11:00:00Z')])[0].json.freeTimeSlots;
T('FS2 单日 1 个忙会(10-11) → 2 个空档', fs2.length, 2);
T('FS3 空档1=营业开始~会前', [fs2[0].freeStart, fs2[0].freeEnd], ['2026-10-05T08:00:00.000Z','2026-10-05T10:00:00.000Z']);
T('FS4 空档2=会后~营业结束', [fs2[1].freeStart, fs2[1].freeEnd], ['2026-10-05T11:00:00.000Z','2026-10-05T17:30:00.000Z']);
T('FS5 dayOfWeek 用 UTC 星期(2026-10-05=Monday)', fs2[0].dayOfWeek, 'Monday');

// 两会有间隙
let fs6 = freeTimeSlotsFaithful([ev('2026-10-06T09:00:00Z','2026-10-06T10:00:00Z'), ev('2026-10-06T14:00:00Z','2026-10-06T15:00:00Z')])[0].json.freeTimeSlots;
T('FS6 两会夹缝 → 3 空档(前/中/后)', fs6.map(x=>[x.freeStart,x.freeEnd]), [
  ['2026-10-06T08:00:00.000Z','2026-10-06T09:00:00.000Z'],
  ['2026-10-06T10:00:00.000Z','2026-10-06T14:00:00.000Z'],
  ['2026-10-06T15:00:00.000Z','2026-10-06T17:30:00.000Z']]);

// 全天排满 → 无空档
let fs7 = freeTimeSlotsFaithful([ev('2026-10-07T08:00:00Z','2026-10-07T17:30:00Z')])[0].json.freeTimeSlots;
T('FS7 全时段排满 → 0 空档', fs7.length, 0);

// 跨天：min~max 逐日展开，无会议日整天算空
let fs8 = freeTimeSlotsFaithful([ev('2026-10-05T10:00:00Z','2026-10-05T11:00:00Z'), ev('2026-10-08T10:00:00Z','2026-10-08T11:00:00Z')])[0].json.freeTimeSlots;
T('FS8 跨 4 天 → 中间无会日各出 1 个全天档，共 2+1+1+2=6', fs8.length, 6);

// 🚨 坑：周末不排除（systemMessage 说周末不约，但 Code 不知道）
let fs9 = freeTimeSlotsFaithful([ev('2026-10-10T10:00:00Z','2026-10-10T11:00:00Z')])[0].json.freeTimeSlots; // 2026-10-10=Saturday
T('FS9 周六照样出空档（坑：Code 不排除周末，靠 prompt 约束）', fs9.every(x=>x.dayOfWeek==='Saturday'), true);

// 🚨 坑：showAs != busy 的事件被忽略（free/tentative 不占档）
let fs10 = freeTimeSlotsFaithful([ev('2026-10-09T09:00:00Z','2026-10-09T10:00:00Z','free')])[0].json.freeTimeSlots;
T('FS10 showAs=free 事件不占档 → 1 个全天档', fs10.length, 1);

// 🚨 坑：营业前结束的会议(07:00-07:30) → 空档起点=07:30 早于营业开始 08:00，算法不裁剪营业时间（如实复刻）
let fs11 = freeTimeSlotsFaithful([ev('2026-10-05T07:00:00Z','2026-10-05T07:30:00Z')])[0].json.freeTimeSlots;
T('FS11 坑实锤：营业前结束的会议产生 07:30 空档起点（<08:00 营业时间外）', fs11[0].freeStart, '2026-10-05T07:30:00.000Z');
T('FS12 同理：该日共 1 个空档且 freeEnd=17:30', [fs11.length, fs11[0].freeEnd], [1, '2026-10-05T17:30:00.000Z']);

// --- If chatInput exists（3 断言）---
T('IF1 chatInput 有值 → true(走 AI Agent)', chatInputExists({chatInput:'hello'}), true);
T('IF2 无 chatInput(首次握手) → false(走固定欢迎语)', chatInputExists({sessionId:'abc'}), false);
T('IF3 chatInput=空串也存在(exists 非 isNotEmpty)', chatInputExists({chatInput:''}), true);

// --- Switch route（4 断言）---
T('SW1 route=availability → out0', switchRoute('availability'), 'out0:availability');
T('SW2 route=message → out1', switchRoute('message'), 'out1:message');
T('SW3 route 其他值 → 静默丢（坑：无 default 分支）', switchRoute('booking'), 'drop(无default分支,静默丢)');
T('SW4 route 大小写敏感(strict)', switchRoute('Availability'), 'drop(无default分支,静默丢)');

// --- varResponse toJsonString（2 断言）---
T('SET1 varResponse 输出是 JSON 字符串不是数组', typeof toJsonStringPolyfill(fs6), 'string');
T('SET2 序列化可逆', JSON.parse(toJsonStringPolyfill(fs6)).length, 3);

const failed = results.filter(x => !x.ok);
return [{ json: { total: results.length, passed: results.length - failed.length, failed: failed.length, failures: failed.map(f => ({name: f.name, actual: f.actual, expected: f.expected})) } }];
